<div class="heading"><h2>Produtos</h2><a class="btn" href="<?= e(url('produtos','create')) ?>">+ Novo produto</a></div>
<div class="table-box"><table><thead><tr><th>ID</th><th>Nome</th><th>Descrição</th><th>Preço</th><th>Categoria</th><th>Ações</th></tr></thead><tbody>
<?php foreach($registros as $r): ?><tr><td><?= e($r['id']) ?></td><td><?= e($r['nome']) ?></td><td><?= e($r['descricao']) ?></td><td>R$ <?= e(number_format((float)$r['preco'],2,',','.')) ?></td><td><?= e($r['categoria_nome']) ?></td><td class="actions"><a class="btn small" href="<?= e(url('produtos','edit',(int)$r['id'])) ?>">Editar</a><form method="post" action="<?= e(url('produtos','delete',(int)$r['id'])) ?>" onsubmit="return confirm('Excluir este produto?');"><input type="hidden" name="token" value="<?= e(token()) ?>"><button type="submit" class="btn danger small">Excluir</button></form></td></tr><?php endforeach; ?>
